            "materials": {
              "notes": [
                {
                  "code": "CONCORD_SUBJECTVERB_101",
                  "title": "Subject-Verb Agreement",
                  "image": "subject_verb_agreement.jpg",
                  "duration": 800,
                  "content": "Subject-verb agreement refers to the grammatical rule that the verb must agree in number with its subject. For example, 'He runs' (singular subject) vs. 'They run' (plural subject)."
                },
                {
                  "code": "CONCORD_PRONOUN_102",
                  "title": "Pronoun-Antecedent Agreement",
                  "image": "pronoun_antecedent.jpg",
                  "duration": 800,
                  "content": "Pronoun-antecedent agreement means that a pronoun must agree in number, gender, and person with its antecedent. For example, 'Each student must bring his or her book.'"
                },
                {
                  "code": "CONCORD_CORRELATIVE_103",
                  "title": "Correlative Conjunctions",
                  "image": "correlative_conjunctions.jpg",
                  "duration": 800,
                  "content": "Correlative conjunctions (either...or, neither...nor, not only...but also) must join equal grammatical elements and ensure verb agreement with the closest subject. For example, 'Neither the teacher nor the students are present.'"
                }
              ],
              "videos": [],
              "audios": [],
